int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    int length = *p++;

    if (length == 0)
        return 1;

    if (length < 2)
        return 0;

    while (length >= 2) {
        int type = *p++;
        int len = *p++;

        length -= 2;

        if (len < 0 || len > length)
            return 0;

        switch (type) {
        case ROSE_FACILITY_NATIONAL:
            if (!parse_national_facility(p, len, facilities))
                return 0;
            break;
        case ROSE_FACILITY_CCITT:
            if (!parse_ccitt_facility(p, len, facilities))
                return 0;
            break;
        default:
            ROS_DEBUG("Unknown facility type %d", type);
            break;
        }

        p += len;
        length -= len;
    }

    return 1;
}

int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    int length = *p++;

    if (length == 0)
        return 1;

    facilities->count = 0;
    facilities->facility = NULL;

    while (length > 0) {
        int type = *p++;
        int len = *p++;
        length -= 2;

        if (len > length) {
            return 0;
        }

        if (type == ROSE_FACILITY_NATIONAL) {
            if (!parse_national_facility(p, len, facilities))
                return 0;
        } else if (type == ROSE_FACILITY_CCITT) {
            if (!parse_ccitt_facility(p, len, facilities))
                return 0;
        } else {
            // Log debug message for unknown facility type
#ifdef DEBUG
            printf("Unknown facility type: 0x%x, length: %d\n", type, len);
#endif
        }

        p += len;
        length -= len;
    }

    return 1;
}

int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    unsigned int length;

    length = *p++;

    if (length == 0)
        return 1;

    if (length % 2 == 1)
        length--;

    while (length > 0) {
        unsigned int facility_length = *p++;

        if (facility_length == 0)
            break;

        if (facility_length > length)
            return 0;

        switch (*p) {
        case ROSE_FACILITY_NATIONAL:
            if (!parse_national_facility(p, facilities))
                return 0;
            break;
        case ROSE_FACILITY_CCITT:
            if (!parse_ccitt_facility(p, facilities))
                return 0;
            break;
        default:
            printk(KERN_DEBUG "ROSE: Unknown facility type 0x%02X\n", *p);
            break;
        }

        p += facility_length;
        length -= facility_length;
    }

    return 1;
}

int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    int len;

    len = *p++;
    if (len == 0)
        return 1;

    if (len < 2)
        return 0;

    while (len > 0) {
        int facility_type = (*p << 8) | *(p + 1);
        int facility_length = *(p + 2);

        if (facility_length < 2) {
            return 0;
        }

        if (facility_length > len) {
            return 0;
        }

        switch (facility_type) {
            case ROSE_FACILITY_NATIONAL:
                if (!parse_national_facility(p + 3, facility_length - 2, facilities))
                    return 0;
                break;
            case ROSE_FACILITY_CCITT:
                if (!parse_ccitt_facility(p + 3, facility_length - 2, facilities))
                    return 0;
                break;
            default:
                // Log debug message for unknown facility type
                printk(KERN_DEBUG "ROSE: Unknown facility type 0x%04X, ignoring.\n", facility_type);
        }

        len -= facility_length + 2;
        p += facility_length + 2;
    }

    return 1;
}

int parse_facilities(unsigned char *p, struct rose_facilities_struct *facilities) {
    unsigned char length;

    if (!p || !facilities)
        return 0;

    length = *p++;

    if (length == 0)
        return 1;

    if (length % 2 != 0)
        return 0;

    while (length > 0) {
        int type = *p++;

        switch (type) {
            case ROSE_FACILITY_NATIONAL:
                if (!parse_national_facility(p, facilities))
                    return 0;
                break;
            case ROSE_FACILITY_CCITT:
                if (!parse_ccitt_facility(p, facilities))
                    return 0;
                break;
            default:
                // Log debug message: unknown facility type
                fprintf(stderr, "Unknown facility type: %d\n", type);
        }

        length -= 2;
        p += 1;
    }

    return 1;
}
